package com.example.marketplace.claim.infrastructure;

import com.example.marketplace.claim.api.ExchangeViews;
import com.example.marketplace.claim.api.Exchanges;
import com.example.marketplace.order.api.OrderQueries;
import com.example.marketplace.order.api.OrderRejected;
import com.example.marketplace.order.api.Orders;
import com.example.marketplace.order.api.ExchangeApplications;
import com.example.marketplace.order.api.AftercareSettlements;
import com.example.marketplace.inventory.api.ExchangeReservations;
import com.example.marketplace.catalog.api.ExchangeOffers;
import com.example.marketplace.seller.api.Stores;
import com.example.marketplace.payment.api.Refunds;
import java.time.Instant;
import java.sql.Timestamp;
import java.util.List;
import java.util.Map;
import java.util.UUID;
import org.springframework.stereotype.Service;
import org.springframework.context.annotation.Profile;
import org.springframework.jdbc.core.namedparam.NamedParameterJdbcTemplate;
import org.springframework.jdbc.core.namedparam.MapSqlParameterSource;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;

/** Claim-only SQL. Authority, original money/units, current payments and order completion use public ports. */
@Service @Profile("db")
public final class JdbcExchangeViews implements ExchangeViews {
 private enum Actor { BUYER, SELLER, SUPPORT }
 private final NamedParameterJdbcTemplate jdbc;private final OrderQueries queries;private final Orders orders;private final ExchangeApplications applications;private final AftercareSettlements aftercare;private final JdbcExchanges exchanges;private final ExchangeReservations stock;private final ExchangeOffers offers;private final Stores stores;private final Refunds refunds;private final CurrentSupport support;private final JdbcReturnQueries shipping;private final TransactionTemplate tx;
 public JdbcExchangeViews(NamedParameterJdbcTemplate jdbc,OrderQueries queries,Orders orders,ExchangeApplications applications,AftercareSettlements aftercare,JdbcExchanges exchanges,ExchangeReservations stock,ExchangeOffers offers,Stores stores,Refunds refunds,CurrentSupport support,JdbcReturnQueries shipping,PlatformTransactionManager manager) { this.jdbc=jdbc;this.queries=queries;this.orders=orders;this.applications=applications;this.aftercare=aftercare;this.exchanges=exchanges;this.stock=stock;this.offers=offers;this.stores=stores;this.refunds=refunds;this.support=support;this.shipping=shipping;this.tx=new TransactionTemplate(manager); }
 @Override public Current owner(String number,UUID id,OrderQueries.Authority a) { return tx.execute(t->read(Actor.BUYER,number,id,a)); }
 @Override public Current seller(UUID id,OrderQueries.Authority a) { return tx.execute(t->read(Actor.SELLER,null,id,a)); }
 @Override public Current support(String number,UUID id,OrderQueries.Authority a) { return tx.execute(t->read(Actor.SUPPORT,number,id,a)); }
 private void authority(Actor actor,String number,UUID seller,OrderQueries.Authority a) { switch(actor){case BUYER->queries.lockOwned(number,a);case SELLER->queries.lockSellerOrder(seller,a);case SUPPORT->support.require(a);} }
 private Current read(Actor actor,String number,UUID id,OrderQueries.Authority a) {
  if(id==null){throw new OrderRejected(400);}if(actor==Actor.SUPPORT){support.require(a);}var hint=exchanges.source(id);if(actor==Actor.SELLER){number=queries.lockSellerOrder(hint.sellerOrderId(),a).orderNumber();}else if(actor==Actor.BUYER){if(!queries.lockOwned(number,a).id().equals(hint.orderId())){throw new OrderRejected(404);}}else if(!orders.lock(number).id().equals(hint.orderId())){throw new OrderRejected(404);}
  var settlement=aftercare.lockAftercare(hint.sellerOrderId());var app=switch(actor){case BUYER->applications.lockOwner(number,a,id);case SELLER->applications.lockRecorded(id);case SUPPORT->applications.lockRecorded(id);};if(!app.orderId().equals(settlement.orderId())||!app.sellerOrderId().equals(settlement.sellerOrderId())){throw new OrderRejected(409);}var row=exchanges.lock(id);var progress=exchanges.progress(id);var extension=extension(id);var eligibility=eligibility(actor,app,row,progress,extension);var financial=financial(actor,app,settlement,row);var s=shipping.shipping(settlement);Origin origin=s.originIntentId()==null?null:new Origin(s.originKind(),s.originIntentId(),s.supportContract(),s.commandRevisionKind().equals("CANCEL_CLAIM")?"CLAIM_REVISION":"SHIPPING_OPERATION",s.commandRevision());var payment=s.refundAttemptId()==null?null:new Refund(s.refundAttemptId(),"SHIPPING",s.sequence(),s.resultVersion(),s.resultState(),s.amount(),s.reference(),s.resultAt(),actor==Actor.SUPPORT?s.supportActions():List.of());var originalShipping=new Shipping(s.decision(),s.reason(),s.refundAttemptId()==null?null:s.revision(),s.state().equals("NONE")?"NOT_RESERVED":s.state(),Long.toString(settlement.originalShipping()),origin,payment);
  var saved=orders.find(settlement.orderNumber());var subjects=app.units().stream().map(u->{var item=saved.sellers().stream().filter(v->v.id().equals(app.sellerOrderId())).flatMap(v->v.items().stream()).filter(v->v.id().equals(u.itemId())).findFirst().orElseThrow(()->new OrderRejected(409));var line=saved.quote().stores().stream().flatMap(v->v.lines().stream()).filter(v->v.skuId().equals(item.skuId())).findFirst().orElseThrow(()->new OrderRejected(409));return new Subject(u.itemId(),u.ordinal(),line.title(),u.originalUnitPrice(),u.originalNet(),u.returnPolicy());}).toList();boolean delivered=progress.state().equals("COMPLETED")&&jdbc.queryForObject("SELECT count(*) FROM marketplace.claim_exchange_completion WHERE exchange_id=:id",Map.of("id",id),Integer.class)==1;if(progress.state().equals("COMPLETED")&&!delivered){throw new OrderRejected(409);}authority(actor,number,app.sellerOrderId(),a);return new Current(progress,actor.name(),saved.state(),subjects,eligibility,extension,financial,originalShipping,delivered);
 }
 private Extension extension(UUID id) { var rows=jdbc.queryForList("SELECT * FROM marketplace.claim_exchange_extension WHERE exchange_id=:id",Map.of("id",id));if(rows.isEmpty()){return null;}if(rows.size()!=1){throw new OrderRejected(409);}var r=rows.getFirst();return new Extension(((Number)r.get("sequence")).intValue(),instant(r.get("previous_expires_at")),instant(r.get("extended_expires_at")),instant(r.get("extended_at")),r.get("reason").toString()); }
 private Eligibility eligibility(Actor actor,ExchangeApplications.Source app,Map<String,Object> row,Exchanges.Progress p,Extension extension) {
  String storeState="UNAVAILABLE";boolean target=false;try{var trade=stores.existingTrade(app.storeId());storeState=trade.state();target=trade.state().equals("OPEN")&&trade.visible()||List.of("SUSPENDED","CLOSED").contains(trade.state())&&inspectedSeller(p);for(var unit:p.accepted().units()){var original=app.units().stream().filter(v->v.itemId().equals(unit.itemId())&&v.ordinal()==unit.ordinal()).findFirst().orElseThrow(()->new OrderRejected(409));if(!offers.existingPublished(app.storeId(),unit.targetSkuId()).price().equals(original.originalUnitPrice())){target=false;}}}catch(com.example.marketplace.catalog.api.CatalogException|com.example.marketplace.seller.api.StoreException unavailable){target=false;}
  int sequence=((Number)row.get("current_sequence")).intValue();var current=stock.get(app.id()).stream().filter(v->v.sequence()==sequence).toList();boolean pending=List.of("REQUESTED","RESPONSIBILITY_PENDING","APPROVED","COLLECTING","READY","REVIEW_REQUIRED","DISPATCH_PENDING","EXPIRED").contains(p.state());boolean noDispatch=jdbc.queryForObject("SELECT count(*) FROM marketplace.claim_exchange_dispatch_effect WHERE exchange_id=:id",Map.of("id",app.id()),Integer.class)==0;boolean canApprove=actor==Actor.SELLER&&target&&noDispatch&&(sequence==0&&pending||sequence>0&&List.of("EXPIRED","REVIEW_REQUIRED").contains(p.state())&&!current.isEmpty()&&current.stream().allMatch(v->v.status().equals("EXPIRED")));boolean prePhysical=List.of("REQUESTED","RESPONSIBILITY_PENDING","APPROVED","COLLECTING","REVIEW_REQUIRED").contains(p.state());boolean receive=actor==Actor.SELLER&&prePhysical&&p.physical().stream().anyMatch(v->!v.collection().equals("RECEIVED")&&v.inspectionId()==null);boolean inspect=actor==Actor.SELLER&&prePhysical&&p.physical().stream().anyMatch(v->v.collection().equals("RECEIVED")&&v.inspectionId()==null);Instant now=jdbc.queryForObject("SELECT clock_timestamp()",Map.of(),Timestamp.class).toInstant();boolean reserved=!current.isEmpty()&&current.stream().allMatch(v->v.status().equals("RESERVED")&&now.isBefore(v.expiresAt()));boolean reship=actor==Actor.SELLER&&target&&p.state().equals("READY")&&reserved&&noDispatch&&inspected(p);boolean extend=actor==Actor.SELLER&&extension==null&&reserved&&noDispatch&&List.of("APPROVED","COLLECTING","READY","REVIEW_REQUIRED","DISPATCH_PENDING").contains(p.state());boolean quote=actor==Actor.BUYER&&pending&&noDispatch&&inspected(p)&&jdbc.queryForObject("SELECT count(*) FROM marketplace.claim_exchange_refund_consent WHERE exchange_id=:id",Map.of("id",app.id()),Integer.class)==0;return new Eligibility(storeState,canApprove,receive,inspect,reship,extend,quote,storeState.equals("SUSPENDED")||storeState.equals("CLOSED")?"정지·폐점 기존 거래는 실제 검수로 판매자 책임이 확인된 경우에만 재고 승인합니다.":"현재 재고·자격·가격·기한은 요청을 처리할 때 다시 확인합니다.");
 }
 private static boolean inspected(Exchanges.Progress p) { return !p.physical().isEmpty()&&p.physical().size()==p.accepted().units().size()&&p.physical().stream().allMatch(v->v.collection().equals("RECEIVED")&&v.inspectionId()!=null&&List.of("SALEABLE","DEFECTIVE").contains(v.inspection())&&(!v.inspection().equals("SALEABLE")||v.restitutionId()!=null)); }
 private static boolean inspectedSeller(Exchanges.Progress p) { return inspected(p)&&p.physical().stream().allMatch(v->v.responsibility()==Exchanges.Responsibility.SELLER); }
 private Financial financial(Actor actor,ExchangeApplications.Source app,AftercareSettlements.AftercareView view,Map<String,Object> row) {
  var cs=jdbc.queryForList("SELECT * FROM marketplace.claim_exchange_refund_consent WHERE exchange_id=:id",Map.of("id",app.id()));if(cs.isEmpty()){return null;}if(cs.size()!=1){throw new OrderRejected(409);}var c=cs.getFirst();var a=jdbc.queryForMap("SELECT * FROM marketplace.claim_fee_assessment WHERE id=:id AND intent_id=:intent",Map.of("id",c.get("assessment_id"),"intent",app.id()));UUID attempt=jdbc.queryForObject("SELECT attempt_id FROM marketplace.claim_fee_binding WHERE assessment_id=:id",Map.of("id",a.get("id")),UUID.class);var actual=refunds.get(attempt);if(!actual.claimId().equals(app.id())||!actual.orderId().equals(app.orderId())||!actual.sellerOrderId().equals(app.sellerOrderId())||!actual.purpose().equals("ITEM")||actual.amount()!=((Number)a.get("refund")).longValue()||!refunds.originalReference(attempt).equals(a.get("quote_fingerprint"))){throw new OrderRejected(409);}boolean ready=jdbc.queryForObject("SELECT count(*) FROM marketplace.claim_exchange_refund_item_ready WHERE exchange_id=:id",Map.of("id",app.id()),Integer.class)==1;boolean done=jdbc.queryForObject("SELECT count(*) FROM marketplace.claim_exchange_refund_completion WHERE exchange_id=:id",Map.of("id",app.id()),Integer.class)==1;if(done&&(!row.get("state").equals("REFUNDED")||!ready||!a.get("state").equals("APPLIED")||((Number)a.get("additional_due")).longValue()!=0||!actual.state().equals("SUCCEEDED")||actual.resultReference()==null||actual.resultAt()==null||view.units().stream().filter(v->app.units().stream().anyMatch(u->u.itemId().equals(v.itemId())&&u.ordinal()==v.ordinal())).anyMatch(v->!app.id().equals(v.exchangeRefundCompletionId())))){throw new OrderRejected(409);}var actions=actor==Actor.SUPPORT&&view.orderState().equals("PAID")&&!done?(actual.state().equals("FAILED")?List.of("RETRY"):List.of("UNKNOWN","PROCESSING").contains(actual.state())?List.of("QUERY"):List.<String>of()):List.<String>of();return new Financial((UUID)c.get("id"),(UUID)a.get("id"),a.get("state").toString(),money(a,"net"),money(a,"increment"),money(a,"refund"),money(a,"additional_due"),new Refund(attempt,"ITEM",actual.sequence(),actual.version(),actual.state(),Long.toString(actual.amount()),actual.resultReference(),actual.resultAt(),actions),ready,done);
 }
 @Override public Page support(String number,OrderQueries.Authority a,int size,String cursor) {
  if(size<1||size>50){throw new OrderRejected(400);}return tx.execute(t->{support.require(a);var parent=orders.lock(number);var p=new MapSqlParameterSource("order",parent.id()).addValue("limit",size+1);String boundary="";if(cursor!=null){try{var parts=new String(java.util.Base64.getUrlDecoder().decode(cursor),java.nio.charset.StandardCharsets.UTF_8).split("\\|",-1);if(parts.length!=2){throw new IllegalArgumentException();}p.addValue("at",Timestamp.from(Instant.parse(parts[0]))).addValue("id",UUID.fromString(parts[1]));boundary=" AND(requested_at,id)<(:at,:id)";}catch(IllegalArgumentException invalid){throw new OrderRejected(400);}}var rows=jdbc.queryForList("SELECT id,requested_at FROM marketplace.claim_exchange_request WHERE order_id=:order"+boundary+" ORDER BY requested_at DESC,id DESC LIMIT :limit",p);var values=rows.stream().limit(size).map(r->exchanges.progress((UUID)r.get("id"))).toList();String next=null;if(rows.size()>size){var last=rows.get(size-1);next=java.util.Base64.getUrlEncoder().withoutPadding().encodeToString((instant(last.get("requested_at"))+"|"+last.get("id")).getBytes(java.nio.charset.StandardCharsets.UTF_8));}support.require(a);return new Page(-1,values,List.of(),next);});
 }
 private static Instant instant(Object value) { return ((Timestamp)value).toInstant(); }
 private static String money(Map<String,Object> row,String key) { return Long.toString(((Number)row.get(key)).longValue()); }
}
